# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def name_order(student: Student) -> str:
    """Sort key so names compare without regard to case."""
    return student.display_name.casefold()

# ---
def missing_emails(ordered: List[Student]) -> List[str]:
    """Display names of students with no email on file."""
    missing = [item for item in ordered if not item.email]
    return [item.display_name for item in missing]

# ---
def check_contacts(ordered: List[Student]) -> None:
    """Refuse an empty list or a student with no email."""
    if not ordered:
        raise ValueError("no students to list")
    missing = missing_emails(ordered)
    if missing:
        names = "; ".join(missing)
        raise ValueError(f"no email on file for: {names}")

# ---
def column_widths(
    ordered: List[Student]
) -> Tuple[int, int]:
    """Widest name and section, to pad the columns."""
    names = [item.display_name for item in ordered]
    sections = [item.section for item in ordered]
    return max(map(len, names)), max(map(len, sections))

# ---
def format_row(
    item: Student, widths: Tuple[int, int]
) -> str:
    name_width, section_width = widths
    return (
        f"{item.display_name:<{name_width}}  "
        f"{item.section:<{section_width}}  {item.email}"
    )

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """One aligned text row per student, sorted by name."""
    ordered = sorted(students, key=name_order)
    check_contacts(ordered)
    widths = column_widths(ordered)
    return [format_row(item, widths) for item in ordered]
